package au.monster.tracker;
import java.util.*;

/** Refunds are separate from undo: original payment fees remain, returned stock is explicitly received. */
public final class Refunds {
    public record Request(String id,String saleId,long amount,long recordedAt,String note,boolean stripe){public Request{Purchases.checkId(id);Purchases.checkId(saleId);Ledger.checkMoney(amount);if(amount<1||recordedAt<946684800000L||recordedAt>4102444800000L||note==null||note.length()>500)Purchases.bad("Invalid refund request.");}}
    public record Observation(String id,String requestId,String providerId,String status,Long created,long verifiedAt,Long fee,String failureReason){public Observation{Purchases.checkId(id);Purchases.checkId(requestId);if(providerId==null||providerId.length()>120||!Ledger.set("pending","requires_action","succeeded","failed","canceled").contains(status)||(created!=null&&(created<946684800000L||created>4102444800000L))||verifiedAt<946684800000L||verifiedAt>4102444800000L||(fee!=null&&(fee < -Ledger.MAX_MONEY||fee > Ledger.MAX_MONEY))||failureReason==null||failureReason.length()>500)Purchases.bad("Invalid refund verification.");}}
    public record Return(String id,String requestId,String eventId,long quantity,long recordedAt){public Return{Purchases.checkId(id);Purchases.checkId(requestId);Purchases.checkId(eventId);if(quantity<1||quantity>2||recordedAt<946684800000L||recordedAt>4102444800000L)Purchases.bad("Invalid received returned goods.");}}
    public record State(long amount,long cash,long card,long fees,long unknownFees,Map<String,Observation> latest){}
    public static State state(List<Request> requests,List<Observation> observations,List<Ledger.Event> events){Map<String,Observation> latest=new LinkedHashMap<>();for(var o:observations)latest.put(o.requestId,o);Map<String,Ledger.Event> sales=new HashMap<>();for(var e:events)sales.put(e.id(),e);long amount=0,cash=0,card=0,fees=0,unknown=0;for(var request:requests){var o=latest.get(request.id);if(o==null)continue;if(o.fee!=null)fees+=o.fee;if(o.status.equals("succeeded")){amount+=request.amount;var e=sales.get(request.saleId);if(e.payment().equals("cash"))cash+=request.amount;else card+=request.amount;if(o.fee==null)unknown++;}}return new State(amount,cash,card,fees,unknown,Collections.unmodifiableMap(latest));}
    public static Map<String,Object> requestMap(Request r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.id);m.put("saleId",r.saleId);m.put("amount",r.amount);m.put("recordedAt",r.recordedAt);m.put("note",r.note);m.put("stripe",r.stripe);return m;}
    public static Request request(Object value){var m=Purchases.map(value);return new Request(Purchases.str(m,"id"),Purchases.str(m,"saleId"),Purchases.num(m,"amount"),Purchases.num(m,"recordedAt"),Purchases.str(m,"note"),FinanceBackup.bool(m,"stripe"));}
    public static Map<String,Object> observationMap(Observation o){Map<String,Object> m=new LinkedHashMap<>();m.put("id",o.id);m.put("requestId",o.requestId);m.put("providerId",o.providerId);m.put("status",o.status);m.put("created",o.created);m.put("verifiedAt",o.verifiedAt);m.put("fee",o.fee);m.put("failureReason",o.failureReason);return m;}
    public static Observation observation(Object value){var m=Purchases.map(value);return new Observation(Purchases.str(m,"id"),Purchases.str(m,"requestId"),Purchases.str(m,"providerId"),Purchases.str(m,"status"),m.get("created")==null?null:Purchases.num(m,"created"),Purchases.num(m,"verifiedAt"),m.get("fee")==null?null:Purchases.num(m,"fee"),Purchases.str(m,"failureReason"));}
    public static Map<String,Object> returnMap(Return r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.id);m.put("requestId",r.requestId);m.put("eventId",r.eventId);m.put("quantity",r.quantity);m.put("recordedAt",r.recordedAt);return m;}
    public static Return returned(Object value){var m=Purchases.map(value);return new Return(Purchases.str(m,"id"),Purchases.str(m,"requestId"),Purchases.str(m,"eventId"),Purchases.num(m,"quantity"),Purchases.num(m,"recordedAt"));}
    public static void validate(List<Request> requests,List<Observation> observations,List<Return> returns,List<Ledger.Event> events){Map<String,Ledger.Event> ledger=new HashMap<>();Set<String> undone=new HashSet<>();for(var e:events){ledger.put(e.id(),e);if(e.type().equals("undo"))undone.add(e.target());}Map<String,Request> ids=new HashMap<>();for(var r:requests){var sale=ledger.get(r.saleId);if(ids.put(r.id,r)!=null||sale==null||!Ledger.set("single","deal").contains(sale.type())||r.amount>sale.revenue())Purchases.bad("Invalid refund/sale link or duplicate ID.");if(r.stripe!=java.util.regex.Pattern.compile("^Stripe pi_[A-Za-z0-9]+ ·").matcher(sale.note()).find())Purchases.bad("Stripe refund needs a verified original Stripe sale.");}Set<String> observationsIds=new HashSet<>();Map<String,Observation> chronological=new HashMap<>();Map<String,String> providerOwners=new HashMap<>();for(var o:observations){var r=ids.get(o.requestId);if(!observationsIds.add(o.id)||r==null||(r.stripe?(!o.providerId.matches("re_[A-Za-z0-9]+")||o.created==null):!o.providerId.equals("manual-"+r.id)))Purchases.bad("Invalid refund verification association.");Observation prior=chronological.put(o.requestId,o);if(prior!=null&&(o.verifiedAt<prior.verifiedAt||!Objects.equals(o.created,prior.created)||!o.providerId.equals(prior.providerId)||(o.fee==null&&prior.fee!=null)))Purchases.bad("Inconsistent refund verification timeline.");if(!r.stripe&&ledger.get(r.saleId).payment().equals("cash")&&o.fee!=null&&o.fee!=0)Purchases.bad("Cash refund fees must be zero.");String owner=providerOwners.putIfAbsent(o.providerId,o.requestId);if(owner!=null&&!owner.equals(o.requestId))Purchases.bad("Provider refund was linked twice.");}
        State state=state(requests,observations,events);Map<String,Long> totals=new HashMap<>();for(var r:requests){var o=state.latest.get(r.id);if(o==null||o.status.equals("succeeded")||o.status.equals("pending")||o.status.equals("requires_action"))totals.put(r.saleId,totals.getOrDefault(r.saleId,0L)+r.amount);}for(var e:totals.entrySet())if(e.getValue()>ledger.get(e.getKey()).revenue())Purchases.bad("Refunds exceed the original payment.");Set<String> returnIds=new HashSet<>(),returnEvents=new HashSet<>();Map<String,Long> quantities=new HashMap<>();for(var r:returns){var request=ids.get(r.requestId);var e=ledger.get(r.eventId);if(!returnIds.add(r.id)||!returnEvents.add(r.eventId)||request==null||e==null||!e.type().equals("restock")||e.quantity()!=r.quantity||e.cost()!=0||e.recordedAt()!=r.recordedAt)Purchases.bad("Invalid returned-goods event.");if(!undone.contains(e.id()))quantities.put(request.saleId,quantities.getOrDefault(request.saleId,0L)+r.quantity);}for(var q:quantities.entrySet())if(q.getValue()>ledger.get(q.getKey()).quantity())Purchases.bad("Returned cans exceed the original sale.");for(var r:requests)if(undone.contains(r.saleId)){var latest=state.latest.get(r.id);if(latest==null||!Ledger.set("failed","canceled").contains(latest.status)||quantities.getOrDefault(r.saleId,0L)>0)Purchases.bad("An undone sale cannot have active refunds or received returns.");}
    }
    public static List<Finance.Row> financialRows(List<Request> requests,List<Observation> observations,List<Ledger.Event> events,Map<String,Finance.Tax> taxes,Map<String,List<Catalog.Allocation>> allocations){Map<String,Request> byId=new HashMap<>();for(var r:requests)byId.put(r.id,r);Map<String,Ledger.Event> sales=new HashMap<>();for(var e:events)sales.put(e.id(),e);Map<String,Observation> previous=new HashMap<>();Map<String,Long> active=new HashMap<>();List<Finance.Row> rows=new ArrayList<>();for(var o:observations){var request=byId.get(o.requestId);var sale=sales.get(request.saleId);var prior=previous.put(o.requestId,o);long amountDelta=(o.status.equals("succeeded")?request.amount:0)-(prior!=null&&prior.status.equals("succeeded")?request.amount:0),feeDelta=(o.fee==null?0:o.fee)-(prior==null||prior.fee==null?0:prior.fee),before=active.getOrDefault(sale.id(),0L),after=before+amountDelta;active.put(sale.id(),after);long tax=taxes.getOrDefault(sale.id(),Finance.UNTAXED).outputGst(),gstDelta=tax*after/sale.revenue()-tax*before/sale.revenue();long quantity=0;for(var allocation:Catalog.forEvent(sale,allocations)){long gross=portion(-amountDelta,quantity,allocation.quantity(),sale.quantity()),gst=portion(-gstDelta,quantity,allocation.quantity(),sale.quantity()),fee=portion(feeDelta,quantity,allocation.quantity(),sale.quantity());quantity+=allocation.quantity();if(amountDelta!=0||feeDelta!=0)rows.add(new Finance.Row(o.id,"refund",!request.stripe&&prior==null&&o.status.equals("succeeded")?o.created:Long.valueOf(o.verifiedAt),allocation.productId(),gross,sale.payment().equals("cash")?gross:0,sale.payment().equals("card")?gross:0,fee,0,0,0,0,gst,0,"Refund "+o.providerId+" · "+o.status+" · source sale "+sale.id()+" · "+request.note));}}return rows;}
    private static long portion(long total,long before,long quantity,long sum){return total*(before+quantity)/sum-total*before/sum;}
    public static Map<String,Object> export(List<Request> requests,List<Observation> observations,List<Return> returns){Map<String,Object> m=new LinkedHashMap<>();List<Object> rs=new ArrayList<>(),os=new ArrayList<>(),gs=new ArrayList<>();for(var r:requests)rs.add(requestMap(r));for(var o:observations)os.add(observationMap(o));for(var g:returns)gs.add(returnMap(g));m.put("requests",rs);m.put("observations",os);m.put("returns",gs);return m;}
    public static List<Request> requests(Map<String,Object> all){List<Request> r=new ArrayList<>();for(Object value:Purchases.list(all.get("requests")))r.add(request(value));return r;}
    public static List<Observation> observations(Map<String,Object> all){List<Observation> r=new ArrayList<>();for(Object value:Purchases.list(all.get("observations")))r.add(observation(value));return r;}
    public static List<Return> returns(Map<String,Object> all){List<Return> r=new ArrayList<>();for(Object value:Purchases.list(all.get("returns")))r.add(returned(value));return r;}
    public static void validate(Map<String,Object> data,List<Ledger.Event> events){if(!data.keySet().equals(Ledger.set("requests","observations","returns")))Purchases.bad("Invalid refund backup fields.");validate(requests(data),observations(data),returns(data),events);}
    private Refunds(){}
}
